(function () {
  'use strict';
  const KEY = 'fos_v2_talent_applications';
  const DRAFT = 'fos_v2_talent_draft';
  const TALENT_FIELDS = [
    ['بحث علمي','البحث العلمي'],['مشروعات بحثية','المشروعات البحثية'],['ابتكار واختراع','الابتكار والاختراع'],['برمجة وتطبيقات','البرمجة وتطوير التطبيقات'],['ذكاء اصطناعي','الذكاء الاصطناعي'],['تكنولوجيا ومهارات رقمية','التكنولوجيا والمهارات الرقمية'],['رسم وفنون تشكيلية','الرسم والفنون التشكيلية'],['أعمال يدوية وخزف','الأعمال اليدوية والخزف'],['خط عربي','الخط العربي'],['تصوير','التصوير'],['كتابة أدبية','الكتابة الأدبية'],['قصة قصيرة وخيال علمي','القصة القصيرة والخيال العلمي'],['شعر','الشعر'],['مسرح وتمثيل','المسرح والتمثيل'],['إنشاد ديني','الإنشاد الديني'],['رياضة','الرياضة'],['قيادة وعمل تطوعي','القيادة والعمل التطوعي'],['مجال آخر','مجال آخر']
  ];
  const NEEDS = ['دورات تدريبية','ورش عمل متخصصة','دعم البحث العلمي','الإشراف الأكاديمي','تطوير فكرة أو مشروع','المشاركة في المسابقات والمعارض','تطوير المهارات الفنية والأدبية','التدريب على العروض التقديمية والبوسترات','التدريب على البرمجة والتكنولوجيا','التوجيه إلى فرص ومبادرات مناسبة','المساعدة في اكتشاف الموهبة وتحديد مسار مناسب','احتياج آخر'];
  const STATUSES = { draft:'مسودة', pending_advisor:'تم الإرسال', under_review:'قيد المراجعة', needs_completion:'مطلوب استكمال بيانات', interview:'بانتظار المقابلة أو التقييم', accepted:'تم القبول', deferred:'مؤجل', rejected:'غير مقبول', withdrawn:'منسحب' };
  const esc = v => String(v == null ? '' : v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const user = () => window.App?.getCurrentUser?.() || null;
  const codeOf = u => String(u?.code || u?.student_code || u?.username || '').trim();
  const read = () => { try { return JSON.parse(localStorage.getItem(KEY) || '[]'); } catch (_) { return []; } };
  const write = v => localStorage.setItem(KEY, JSON.stringify(v));
  const readDraft = () => { try { return JSON.parse(localStorage.getItem(DRAFT) || '{}'); } catch (_) { return {}; } };
  const saveDraft = v => { try { localStorage.setItem(DRAFT, JSON.stringify(v)); } catch (_) {} };
  const statusLabel = s => STATUSES[s] || s || 'غير محدد';
  const STATUS_MESSAGES = { pending_advisor:'تم استلام طلبك بنجاح، وسيتم مراجعته من قبل المسؤول المختص.', under_review:'طلبك قيد المراجعة حاليًا. ستظهر هنا أي تحديثات أو إجراءات مطلوبة.', needs_completion:'يتطلب طلبك استكمال بعض البيانات. يرجى مراجعة التعليمات وإرسال المعلومات المطلوبة.', interview:'يتطلب طلبك مقابلة أو تقييمًا إضافيًا. راجع الموعد والتعليمات الظاهرة في التفاصيل.', accepted:'تم قبول طلبك في برنامج دعم الموهوبين.', deferred:'تم تأجيل اتخاذ القرار بشأن طلبك. راجع الملاحظات أو التعليمات لمعرفة الخطوة التالية.', rejected:'تم الانتهاء من مراجعة طلبك ولم تتم الموافقة عليه في هذه المرحلة.', withdrawn:'تم إغلاق الطلب أو انسحبت منه وفق الإجراء المسجل.' };
  const TRANSITIONS = { pending_advisor:['under_review','needs_completion','interview'], under_review:['needs_completion','interview','accepted','deferred','rejected','withdrawn'], needs_completion:['under_review','interview','withdrawn'], interview:['under_review','needs_completion','accepted','deferred','rejected','withdrawn'], deferred:['under_review','accepted','rejected','withdrawn'], accepted:['under_review','withdrawn'], rejected:['under_review'], withdrawn:[] };
  const statusMessage = s => STATUS_MESSAGES[s] || 'يمكنك متابعة آخر تحديثات الطلب من هذه الصفحة.';
  const currentStudent = () => { const u=user()||{}; return { name:u.name||u.full_name||'', code:codeOf(u), level:u.level||'', program:u.program||'', phone:u.phone||'', email:u.email||'' }; };
  const isAdmin = () => user()?.role === 'admin';

  function localMine() { const code=codeOf(user()); return read().filter(x=>String(x.studentCode)===code).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))); }
  async function getMine() {
    if (window.DB?.isOnline?.()) { try { const rows=await DB.listApplications({studentCode:codeOf(user())}); return (rows||[]).filter(x=>x.type==='talent-registration'); } catch (_) {} }
    return localMine();
  }
  async function getAll() {
    if (window.DB?.isOnline?.()) { try { const rows=await DB.listApplications({}); return (rows||[]).filter(x=>x.type==='talent-registration'); } catch (_) {} }
    return read();
  }
  function baseData() { return Object.assign({ talents:[], otherTalent:'', title:'', description:'', experience:'unspecified', duration:'', skills:'', participations:'', achievements:'', training:'', links:'', notes:'', needs:[], otherNeeds:'', declarationAccuracy:false, declarationPrivacy:false }, readDraft(), currentStudent()); }
  function field(id,label,value,attrs='') { return `<label class="talent-field"><span>${label}</span><input id="talent-${id}" class="form-control" value="${esc(value||'')}" ${attrs}></label>`; }
  function renderShell(root, content) { root.innerHTML=`<div class="talent-shell">${content}</div>`; }

  async function renderStudent() {
    const root=document.getElementById('talent-program-root'); if(!root) return;
    if (!user() || (user().role!=='student' && !isAdmin())) { root.innerHTML='<div class="alert alert-warn">هذه الوحدة متاحة للطلاب المسجلين فقط.</div>'; return; }
    if (isAdmin()) return renderAdmin(root);
    const apps=await getMine(); const latest=apps[0];
    const status=latest ? `<div class="talent-status-card"><span class="talent-status-dot"></span><div><small>حالة آخر طلب</small><b>${esc(statusLabel(latest.status))}</b><span>${esc(latest.id||'')} · ${latest.createdAt ? new Date(latest.createdAt).toLocaleString('ar-EG') : ''}</span><p>${esc(latest.talent?.publicMessage || statusMessage(latest.status))}</p></div>${latest.status==='needs_completion'?`<button class="btn btn-sm btn-primary" onclick="TalentProgram.resumeRegistration('${esc(latest.id)}')">استكمال البيانات</button>`:''}<button class="btn btn-sm btn-outline" onclick="TalentProgram.openStudentDetail('${esc(latest.id)}')">عرض التفاصيل</button></div><div class="talent-stage-line">${['pending_advisor','under_review','needs_completion','interview','accepted'].map((s,i)=>`<span class="${latest.status===s?'current':(['under_review','needs_completion','interview','accepted'].indexOf(latest.status)>=i?'done':'')}" title="${statusLabel(s)}"><b>${i+1}</b>${statusLabel(s)}</span>`).join('')}</div>` : '';
    renderShell(root, `<header class="talent-hero"><div><span class="talent-kicker">كلية العلوم · جامعة سوهاج</span><h1>برنامج دعم الموهوبين</h1><p>مساحة لاكتشاف موهبتك وتطويرها عبر التدريب والتوجيه والفرص المناسبة.</p></div><i class="fas fa-star talent-hero-icon"></i></header><div class="talent-actions"><button class="talent-action primary" onclick="TalentProgram.startRegistration()"><i class="fas fa-user-plus"></i><b>${latest ? 'تقديم تسجيل جديد' : 'التسجيل في برنامج دعم الموهوبين'}</b><small>املأ الطلب على خطوات واضحة</small></button><button class="talent-action" disabled title="سيتم تفعيلها في المرحلة الثانية"><i class="fas fa-lightbulb"></i><b>تقديم فكرة أو مشروع</b><small>سيتم تفعيل بنك الأفكار في المرحلة الثانية</small></button><button class="talent-action" onclick="App.navigate('notifications')"><i class="fas fa-bell"></i><b>الإشعارات</b><small>متابعة تحديثات المنصة</small></button></div>${status}<section class="talent-info-grid"><article><i class="fas fa-compass"></i><h2>كيف يعمل البرنامج؟</h2><p>سجل مجالات اهتمامك واحتياجاتك، ثم يراجع المختصون الطلب ويتواصلون معك عند الحاجة إلى استكمال أو تقييم.</p></article><article><i class="fas fa-calendar-check"></i><h2>الأنشطة والفرص</h2><p>سيتم نشر الدورات والورش والمسابقات والفرص التدريبية داخل الوحدة بعد اعتمادها من الإدارة.</p></article><article><i class="fas fa-shield-halved"></i><h2>خصوصية البيانات</h2><p>تستخدم بيانات الطلب للتسجيل والتقييم والتواصل والمتابعة وفق صلاحيات المنصة.</p></article></section><div id="talent-my-list">${apps.length ? `<h2 class="talent-section-title">طلباتي السابقة</h2>${apps.slice(0,5).map(renderMini).join('')}` : '<div class="talent-empty"><i class="fas fa-seedling"></i><b>لم تقدم طلب تسجيل بعد</b><span>ابدأ بتسجيل موهبتك ليتمكن الفريق المختص من دعمك.</span></div>'}</div>`);
  }
  function renderMini(a) { return `<button type="button" class="talent-mini-row" onclick="TalentProgram.openStudentDetail('${esc(a.id)}')"><span class="talent-mini-icon"><i class="fas fa-file-signature"></i></span><div><b>${esc(a.id)}</b><small>${esc((a.talent?.talents||[]).join('، ')||'مجالات متعددة')} · ${a.createdAt ? new Date(a.createdAt).toLocaleDateString('ar-EG') : ''}</small></div><strong class="talent-badge status-${esc(a.status)}">${esc(statusLabel(a.status))}</strong></button>`; }

  async function openStudentDetail(id) {
    const rows = await getMine(), r = rows.find(x => x.id === id); if (!r) return;
    if (window.DB?.isOnline?.() && typeof DB.loadHistory === 'function') { try { r.history = await DB.loadHistory(id); } catch (_) {} }
    const root = document.getElementById('talent-program-root'); if (!root) return;
    const history = (r.history || []).filter(h => h.visibleToStudent !== false).map(h => `<li><b>${esc(h.action || h.step || 'تحديث')}</b><span>${h.at ? new Date(h.at).toLocaleString('ar-EG') : ''}</span>${h.note ? `<small>${esc(h.note)}</small>` : ''}</li>`).join('');
    renderShell(root, `<div class="talent-form-head"><button class="btn btn-sm btn-outline" onclick="TalentProgram.renderStudent()"><i class="fas fa-arrow-right"></i> العودة</button><div><span class="talent-kicker">متابعة الطلب</span><h1>${esc(r.id)}</h1></div></div><section class="talent-detail card"><div class="card-body"><div class="talent-status-card"><span class="talent-status-dot"></span><div><small>الحالة الحالية</small><b>${esc(statusLabel(r.status))}</b><p>${esc(r.talent?.publicMessage || statusMessage(r.status))}</p></div></div><div class="talent-detail-grid"><div><small>تاريخ التقديم</small><b>${r.createdAt ? new Date(r.createdAt).toLocaleString('ar-EG') : '—'}</b></div><div><small>الطالب</small><b>${esc(r.studentName)} · ${esc(r.studentCode)}</b></div><div><small>مجالات الموهبة</small><b>${esc((r.talent?.talents || []).join('، ') || '—')}</b></div><div><small>الاحتياجات</small><b>${esc((r.talent?.needs || []).join('، ') || '—')}</b></div></div><div class="talent-detail-copy"><h3>${esc(r.talent?.title || 'الموهبة')}</h3><p>${esc(r.talent?.description || '')}</p></div><h3 class="talent-section-title">سجل التحديثات</h3><ul class="talent-timeline">${history || '<li><b>تم إرسال الطلب</b><span>سيظهر هنا كل تحديث مسموح بعرضه لك.</span></li>'}</ul></div></section>`);
  }

  async function resumeRegistration(id) { const rows=await getMine(), r=rows.find(x=>x.id===id); if(!r)return; const root=document.getElementById('talent-program-root'); if(!root)return; renderForm(root,Object.assign(baseData(),r.talent||{},{_editingId:id}),1); }
  function startRegistration() {
    const root=document.getElementById('talent-program-root'); if(!root) return;
    const d=baseData(); const step=1;
    renderForm(root,d,step);
  }
  function renderForm(root,d,step) {
    const steps=['البيانات الأساسية','مجالات الموهبة','وصف الموهبة','المرفقات والروابط','احتياجاتك','المراجعة والإقرار'];
    const progress=steps.map((s,i)=>`<span class="${i+1===step?'active':''} ${i+1<step?'done':''}"><b>${i+1}</b>${s}</span>`).join('');
    let panel='';
    if(step===1) panel=`<div class="talent-form-grid">${field('name','الاسم الكامل',d.name,'readonly')}${field('code','الكود الجامعي',d.code,'readonly')}${field('level','المستوى الدراسي',d.level,'readonly')}${field('program','البرنامج أو التخصص',d.program,'readonly')}${field('phone','رقم الهاتف',d.phone,'type="tel" required')}${field('email','البريد الإلكتروني',d.email,'type="email"')}</div><p class="talent-note"><i class="fas fa-circle-info"></i> البيانات الأكاديمية المأخوذة من الحساب للقراءة فقط.</p>`;
    if(step===2) panel=`<p class="talent-help">اختر مجالًا واحدًا أو أكثر، ويمكنك تحديد «مجال آخر» لإضافة مجال غير موجود.</p><div class="talent-check-grid">${TALENT_FIELDS.map(([v,l])=>`<label class="talent-check"><input type="checkbox" data-talent="${esc(v)}" ${d.talents.includes(v)?'checked':''}><span>${esc(l)}</span></label>`).join('')}</div><label class="talent-field talent-other-field"><span>توضيح المجال الآخر (اختياري)</span><input id="talent-otherTalent" class="form-control" value="${esc(d.otherTalent)}"></label>`;
    if(step===3) panel=`<div class="talent-form-grid"><label class="talent-field"><span>عنوان مختصر للموهبة *</span><input id="talent-title" class="form-control" value="${esc(d.title)}" required></label><label class="talent-field"><span>مستوى الخبرة</span><select id="talent-experience" class="form-control"><option value="unspecified">غير محدد</option><option value="beginner" ${d.experience==='beginner'?'selected':''}>مبتدئ</option><option value="intermediate" ${d.experience==='intermediate'?'selected':''}>متوسط</option><option value="advanced" ${d.experience==='advanced'?'selected':''}>متقدم</option></select></label>${field('duration','مدة ممارسة الموهبة',d.duration)}${field('skills','المهارات المرتبطة بها',d.skills)}<label class="talent-field full"><span>الوصف التفصيلي *</span><textarea id="talent-description" class="form-control" rows="4" required>${esc(d.description)}</textarea></label><label class="talent-field full"><span>المشاركات والإنجازات والجوائز</span><textarea id="talent-achievements" class="form-control" rows="3">${esc(d.achievements)}</textarea></label><label class="talent-field full"><span>الدورات التدريبية السابقة والملاحظات</span><textarea id="talent-training" class="form-control" rows="3">${esc(d.training)}</textarea></label></div>`;
    if(step===4) panel=`<div class="talent-attachment-note"><i class="fas fa-paperclip"></i><div><b>الملفات الداعمة</b><p>يمكنك إضافة روابط أعمال أو حسابات مهنية الآن. رفع الملفات الآمن سيُفعّل في مرحلة إدارة المرفقات.</p></div></div><label class="talent-field full"><span>روابط الأعمال أو الحسابات المهنية</span><textarea id="talent-links" class="form-control" rows="4" placeholder="ضع كل رابط في سطر مستقل">${esc(d.links)}</textarea></label><label class="talent-field full"><span>ملاحظات إضافية</span><textarea id="talent-notes" class="form-control" rows="4">${esc(d.notes)}</textarea></label>`;
    if(step===5) panel=`<p class="talent-help">اختر ما تحتاج إليه من دعم، ويمكنك اختيار أكثر من احتياج.</p><div class="talent-check-grid">${NEEDS.map(v=>`<label class="talent-check"><input type="checkbox" data-need="${esc(v)}" ${d.needs.includes(v)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</div><label class="talent-field full"><span>توضيح الاحتياجات الأخرى</span><textarea id="talent-otherNeeds" class="form-control" rows="3">${esc(d.otherNeeds)}</textarea></label>`;
    if(step===6) panel=`<div class="talent-review">${reviewBlock('البيانات الأساسية',`${d.name} · ${d.code} · ${d.level||'—'} · ${d.program||'—'} · ${d.phone||'هاتف غير مسجل'}`)}${reviewBlock('مجالات الموهبة',(d.talents||[]).join('، ')||'لم يتم اختيار مجال')}${reviewBlock('وصف الموهبة',`${d.title||'—'} — ${d.description||'—'}<br><small>الخبرة: ${d.experience||'غير محدد'} · المدة: ${d.duration||'—'}</small>`)}${reviewBlock('الاحتياجات',(d.needs||[]).join('، ')||'لم يتم تحديد احتياج')} </div><label class="talent-declaration"><input id="talent-declarationAccuracy" type="checkbox" ${d.declarationAccuracy?'checked':''}><span>أقر بأن البيانات المقدمة صحيحة بحسب علمي، وأفهم أن التسجيل لا يعني القبول التلقائي أو ضمان الحصول على تدريب أو إشراف أو دعم مالي.</span></label><label class="talent-declaration"><input id="talent-declarationPrivacy" type="checkbox" ${d.declarationPrivacy?'checked':''}><span>أوافق على استخدام البيانات لأغراض التسجيل والتقييم والتواصل والمتابعة وفق سياسة الخصوصية المعتمدة بالجامعة.</span></label>`;
    renderShell(root,`<div class="talent-form-head"><button class="btn btn-sm btn-outline" onclick="TalentProgram.renderStudent()"><i class="fas fa-arrow-right"></i> إلغاء</button><div><span class="talent-kicker">طلب تسجيل جديد</span><h1>التسجيل في برنامج دعم الموهوبين</h1></div></div><div class="talent-progress">${progress}</div><section class="talent-form-card"><h2>${steps[step-1]}</h2><div id="talent-form-panel">${panel}</div><div class="talent-form-actions">${step>1?'<button class="btn btn-outline" id="talent-back"><i class="fas fa-arrow-right"></i> السابق</button>':''}${step<6?'<button class="btn btn-primary" id="talent-next">التالي <i class="fas fa-arrow-left"></i></button>':'<button class="btn btn-primary" id="talent-submit"><i class="fas fa-paper-plane"></i> إرسال طلب التسجيل</button>'}</div></section>`);
    document.getElementById('talent-next')?.addEventListener('click',()=>{const next=collect(d,step);if(!next)return;saveDraft(d);renderForm(root,d,step+1);});
    document.getElementById('talent-back')?.addEventListener('click',()=>{collect(d,step);saveDraft(d);renderForm(root,d,step-1);});
    document.getElementById('talent-submit')?.addEventListener('click',()=>submit(d));
  }
  function reviewBlock(title,body){return `<div class="talent-review-block"><small>${title}</small><div>${body||'—'}</div></div>`;}
  function collect(d,step){
    if(step===1){ d.phone=document.getElementById('talent-phone')?.value.trim()||'';d.email=document.getElementById('talent-email')?.value.trim()||'';if(!d.phone){alert('أدخل رقم الهاتف');return false;} }
    if(step===2){d.talents=[...document.querySelectorAll('[data-talent]:checked')].map(x=>x.dataset.talent);d.otherTalent=document.getElementById('talent-otherTalent')?.value.trim()||'';if(!d.talents.length)return alert('اختر مجال موهبة واحدًا على الأقل');}
    if(step===3){['title','description','duration','skills','achievements','training'].forEach(k=>{const e=document.getElementById('talent-'+k);if(e)d[k]=e.value.trim();});d.experience=document.getElementById('talent-experience')?.value||'unspecified';if(!d.title||!d.description)return alert('أدخل عنوان الموهبة ووصفها التفصيلي');}
    if(step===4){['links','notes'].forEach(k=>{const e=document.getElementById('talent-'+k);if(e)d[k]=e.value.trim();});}
    if(step===5){d.needs=[...document.querySelectorAll('[data-need]:checked')].map(x=>x.dataset.need);d.otherNeeds=document.getElementById('talent-otherNeeds')?.value.trim()||'';}
    if(step===6){d.declarationAccuracy=!!document.getElementById('talent-declarationAccuracy')?.checked;d.declarationPrivacy=!!document.getElementById('talent-declarationPrivacy')?.checked;if(!d.declarationAccuracy||!d.declarationPrivacy){alert('يجب الموافقة على الإقرارين قبل الإرسال');return false;}}
    return true;
  }
  async function submit(d){
    if(!collect(d,6))return;
    const previous=await getMine();
    if(!d._editingId && previous.some(x=>!['rejected','withdrawn'].includes(x.status))){alert('لديك طلب تسجيل قائم بالفعل. يمكنك متابعة حالته من صفحة البرنامج.');return;}
    const u=user(); const id=d._editingId || ('TAL-'+new Date().getFullYear()+'-'+Date.now().toString().slice(-7)); const now=new Date().toISOString();
    const req={id,type:'talent-registration',formTitle:'التسجيل في برنامج دعم الموهوبين',studentName:d.name,studentCode:d.code,level:d.level,program:d.program,phone:d.phone,studentNotes:d.notes,createdAt:previous.find(x=>x.id===id)?.createdAt||now,updatedAt:now,status:d._editingId?'under_review':'pending_advisor',currentStep:0,advisorUsername:u?.advisor||null,talent:{...d},history:[{action:d._editingId?'تم إرسال الاستكمال للمراجعة':'تم إرسال الطلب',at:now,by:d.name,visibleToStudent:true}]};
    const btn=document.getElementById('talent-submit');if(btn){btn.disabled=true;btn.classList.add('is-loading');}
    try{
      if(window.DB?.isOnline?.()){const res=d._editingId?await DB.updateApplication(id,{status:req.status,currentStep:0,requestMetadata:{talent:req.talent}},{step:'talent_completion',by:d.name,role:'student',action:'إرسال الاستكمال للمراجعة',note:'أرسل الطالب البيانات المطلوبة'}):await DB.createApplication(req);if(!res?.ok)throw new Error(res?.error||'تعذر حفظ الطلب على الخادم');}
      else {const all=read();if(d._editingId){const idx=all.findIndex(x=>x.id===id);if(idx>=0){all[idx]={...all[idx],...req,history:[...(all[idx].history||[]),...req.history]};}}else all.unshift(req);write(all);}
      localStorage.removeItem(DRAFT); if(req.studentCode) await window.App?.notifyUser?.(req.studentCode,'تم استلام طلب تسجيلك في برنامج دعم الموهوبين وسيتم مراجعته من الفريق المختص',{title:'تم استلام طلب الموهوبين',type:'success',link:'talent-program'});
      const root=document.getElementById('talent-program-root');renderShell(root,`<div class="talent-success"><span><i class="fas fa-check"></i></span><h1>${d._editingId?'تم إرسال الاستكمال بنجاح':'تم إرسال الطلب بنجاح'}</h1><p>${d._editingId?'تم إرسال البيانات المستكملة للمراجعة من جديد.':'تم حفظ طلبك وإرساله للمراجعة.'} يمكنك متابعة حالته من صفحة برنامج دعم الموهوبين.</p><strong>${esc(id)}</strong><button class="btn btn-primary" onclick="TalentProgram.renderStudent()">متابعة الطلب</button></div>`);
    }catch(e){if(btn){btn.disabled=false;btn.classList.remove('is-loading');}alert(e.message||'تعذر حفظ الطلب');}
  }

  async function renderAdmin(targetRoot){
    const root=targetRoot || document.getElementById('talent-admin-root') || document.getElementById('talent-program-root');if(!root)return;if(!isAdmin()){root.innerHTML='<div class="alert alert-warn">لا تملك صلاحية هذه الشاشة.</div>';return;}
    const rows=await getAll(); const q=document.getElementById('talent-admin-search')?.value||''; const filter=window._talentAdminFilter || document.getElementById('talent-admin-filter')?.value||'all';
    const filtered=rows.filter(r=>(filter==='all'||r.status===filter)&&(!q||[r.id,r.studentName,r.studentCode].join(' ').toLocaleLowerCase('ar').includes(q.toLocaleLowerCase('ar'))));
    const stats=[['all','إجمالي الطلبات',rows.length,'fa-file-signature'],['pending_advisor','الجديدة',rows.filter(r=>r.status==='pending_advisor').length,'fa-inbox'],['under_review','قيد المراجعة',rows.filter(r=>r.status==='under_review').length,'fa-magnifying-glass'],['needs_completion','تحتاج استكمالًا',rows.filter(r=>r.status==='needs_completion').length,'fa-list-check'],['interview','بانتظار التقييم',rows.filter(r=>r.status==='interview').length,'fa-calendar-check'],['accepted','المقبولون',rows.filter(r=>r.status==='accepted').length,'fa-circle-check'],['deferred','المؤجلون',rows.filter(r=>r.status==='deferred').length,'fa-clock'],['rejected','غير المقبولين',rows.filter(r=>r.status==='rejected').length,'fa-circle-xmark']];
    renderShell(root,`<header class="talent-admin-hero"><div><span class="talent-kicker">إدارة الوحدة</span><h1>متابعة طلبات برنامج دعم الموهوبين</h1><p>مراجعة الطلبات وتوثيق الإجراءات وتحديث الحالات وفق الصلاحيات.</p></div><i class="fas fa-star"></i></header><div class="talent-stats">${stats.map(s=>`<button type="button" class="talent-stat-button ${filter===s[0]?'active':''}" onclick="TalentProgram.setAdminFilter('${s[0]}')"><i class="fas ${s[3]}"></i><span>${s[1]}</span><b>${s[2]}</b></button>`).join('')}</div><div class="talent-admin-toolbar"><input id="talent-admin-search" class="form-control" placeholder="بحث بالرقم أو الاسم أو الكود" value="${esc(q)}"><select id="talent-admin-filter" class="form-control"><option value="all">كل الحالات</option>${Object.entries(STATUSES).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn btn-outline" onclick="TalentProgram.resetAdminFilters()"><i class="fas fa-rotate-left"></i> إعادة التعيين</button><button class="btn btn-outline" onclick="TalentProgram.exportCSV()"><i class="fas fa-file-csv"></i> تصدير النتائج</button></div><div class="talent-admin-table table-wrap"><table class="data"><thead><tr><th>المرجع</th><th>الطالب</th><th>المجالات</th><th>التاريخ</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${filtered.length?filtered.map(renderAdminRow).join(''):'<tr><td colspan="6" class="text-center">لا توجد طلبات مطابقة</td></tr>'}</tbody></table></div>`);
    document.getElementById('talent-admin-search')?.addEventListener('input',renderAdmin);document.getElementById('talent-admin-filter')?.addEventListener('change',e=>{window._talentAdminFilter=e.target.value;renderAdmin();});
    root.querySelectorAll('[data-talent-detail]').forEach(button=>button.addEventListener('click',()=>openDetail(button.dataset.talentDetail)));
  }
  function renderAdminRow(r){const talents=r.talent?.talents||[];const last=r.history?.[r.history.length-1];return `<tr><td><b>${esc(r.id)}</b></td><td>${esc(r.studentName)}<small class="block text-muted">${esc(r.studentCode)} · ${esc(r.level||'—')} · ${esc(r.program||'—')}</small></td><td>${esc(talents.slice(0,2).join('، ')||'—')}${talents.length>2?` <small>+${talents.length-2}</small>`:''}</td><td>${r.createdAt?new Date(r.createdAt).toLocaleDateString('ar-EG'):'—'}<small class="text-muted">آخر تحديث: ${r.updatedAt?new Date(r.updatedAt).toLocaleDateString('ar-EG'):'—'}</small></td><td><span class="talent-badge status-${esc(r.status)}">${esc(statusLabel(r.status))}</span><small class="text-muted">${esc(last?.action||'بانتظار الإجراء')}</small></td><td><button type="button" class="btn btn-sm btn-outline" data-talent-detail="${esc(r.id)}">عرض</button></td></tr>`;}
  async function openDetail(id){
    const rows=await getAll(); const r=rows.find(x=>x.id===id); if(!r)return;
    if(window.DB?.isOnline?.() && typeof DB.loadHistory==='function'){try{r.history=await DB.loadHistory(id);}catch(_) {}}
    const root=document.getElementById('talent-admin-root') || document.getElementById('talent-program-root');
    const allowed=TRANSITIONS[r.status]||[];
    const options=[r.status,...allowed.filter(x=>x!==r.status)].map(k=>`<option value="${k}" ${r.status===k?'selected':''}>${statusLabel(k)}</option>`).join('');
    const history=(r.history||[]).map(h=>`<li><b>${esc(h.action||h.step||'إجراء')}</b><span>${h.at?new Date(h.at).toLocaleString('ar-EG'):''}</span>${h.note?`<small>${esc(h.note)}</small>`:''}</li>`).join('');
    root.innerHTML=`<div class="talent-detail card"><div class="card-body"><button class="btn btn-sm btn-outline mb-3" onclick="TalentProgram.renderAdmin()"><i class="fas fa-arrow-right"></i> العودة للقائمة</button><div class="talent-detail-title"><div><span class="talent-kicker">متابعة الطلب</span><h1>${esc(r.id)}</h1></div><span class="talent-badge status-${esc(r.status)}">${esc(statusLabel(r.status))}</span></div><div class="talent-detail-grid"><div><small>الطالب</small><b>${esc(r.studentName)}</b><span>${esc(r.studentCode)} · ${esc(r.level||'—')} · ${esc(r.program||'—')}</span></div><div><small>تاريخ التقديم</small><b>${r.createdAt?new Date(r.createdAt).toLocaleString('ar-EG'):'—'}</b></div><div><small>المجالات</small><b>${esc((r.talent?.talents||[]).join('، ')||'—')}</b></div><div><small>الاحتياجات</small><b>${esc((r.talent?.needs||[]).join('، ')||'—')}</b></div></div><div class="talent-detail-copy"><h3>${esc(r.talent?.title||'عنوان الموهبة')}</h3><p>${esc(r.talent?.description||'')}</p><small>الخبرة: ${esc(r.talent?.experience||'غير محدد')} · الروابط: ${esc(r.talent?.links||'لا توجد')}</small></div><h3 class="talent-section-title">سجل الإجراءات</h3><ul class="talent-timeline">${history||'<li><b>تم إرسال الطلب</b><span>لا توجد إجراءات إضافية بعد.</span></li>'}</ul><div class="talent-admin-action-box"><h3>إجراء إداري</h3><label>الحالة الجديدة<select id="talent-status-change" class="form-control">${options}</select></label><label>رسالة ظاهرة للطالب<textarea id="talent-public-message" class="form-control" rows="3" placeholder="تظهر للطالب في تفاصيل طلبه">${esc(r.talent?.publicMessage||'')}</textarea></label><label>ملاحظة داخلية<textarea id="talent-internal-note" class="form-control" rows="2" placeholder="لا تظهر للطالب"> </textarea></label><button class="btn btn-primary" onclick="TalentProgram.updateStatus('${esc(r.id)}')"><i class="fas fa-save"></i> حفظ الإجراء وإشعار الطالب</button></div></div></div>`;
  }
  async function updateStatus(id){
    const select=document.getElementById('talent-status-change'), status=select?.value; if(!status)return;
    const rows=await getAll(), r=rows.find(x=>x.id===id); if(!r)return;
    const allowed=TRANSITIONS[r.status]||[]; if(status!==r.status&&!allowed.includes(status)){alert('هذا الانتقال غير مسموح من الحالة الحالية.');return;}
    const publicMessage=(document.getElementById('talent-public-message')?.value||'').trim(); const internalNote=(document.getElementById('talent-internal-note')?.value||'').trim();
    if(['accepted','rejected','withdrawn'].includes(status)&&!confirm(`تأكيد القرار النهائي: ${statusLabel(status)}؟`))return;
    const previous=r.status, now=new Date().toISOString(); const nextTalent={...(r.talent||{}),publicMessage};
    try{
      if(window.DB?.isOnline?.()){
        const res=await DB.updateApplication(id,{status,currentStep:0,requestMetadata:{talent:nextTalent}},{step:'talent_status',by:user()?.name||'مدير النظام',role:'admin',action:`${statusLabel(previous)} ← ${statusLabel(status)}`,note:publicMessage||'تم تحديث حالة الطلب'});
        if(!res?.ok)throw new Error(res?.error||'تعذر تحديث الحالة');
      }else{
        r.status=status; r.updatedAt=now; r.talent=nextTalent; r.history=Array.isArray(r.history)?r.history:[]; r.history.push({action:`${statusLabel(previous)} ← ${statusLabel(status)}`,from:previous,to:status,by:user()?.name||'مدير النظام',at:now,note:publicMessage,visibleToStudent:true,internalNote}); write(rows);
      }
      if(r.studentCode)await App.notifyUser(r.studentCode,publicMessage||`تم تحديث حالة طلب دعم الموهوبين الخاص بك إلى: ${statusLabel(status)}`,{title:'تحديث طلب الموهوبين',type:status==='accepted'?'success':status==='rejected'?'error':'info',link:'talent-program'});
      alert('تم حفظ الإجراء وإرسال الإشعار'); renderAdmin();
    }catch(e){alert(e.message||'تعذر تحديث الحالة');}
  }
  function setAdminFilter(filter){ window._talentAdminFilter=filter; renderAdmin(); }
  function resetAdminFilters(){ window._talentAdminFilter='all'; renderAdmin(); }
  function exportCSV(){getAll().then(rows=>{const head=['المرجع','اسم الطالب','الكود','المجالات','الحالة','تاريخ التقديم'];const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\ufeff'+[head,...rows.map(r=>[r.id,r.studentName,r.studentCode,(r.talent?.talents||[]).join('، '),statusLabel(r.status),r.createdAt||''])].map(x=>x.map(cell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='طلبات_دعم_الموهوبين.csv';a.click();URL.revokeObjectURL(a.href);});}
  window.TalentProgram={renderStudent,renderAdmin,startRegistration,resumeRegistration,openDetail,openStudentDetail,updateStatus,setAdminFilter,resetAdminFilters,exportCSV};
})();
